// The mockup's content, worked out from the live map's files at 14:32 on Saturday, 10 October 2026 (#328): the
// day's bundle, snapshot.json and alerts.json, through the app's own engine, closures and cards code.
// Generated by the scratchpad's mkdata.mjs; throwaway with the mockup.

export type Kind = 'commuter' | 'regional' | 'long-distance' | 'metro' | 'tram' | 'rack' | 'funicular';

export interface LineInfo {
  name: string;
  colour: string;
  kind: Kind;
  network: string;
}

/** A Line's state now: its Trains, how many are Live, with no live data (Scheduled though its Network has live data), running 5 minutes or more late, the worst Delay in minutes, and its Cancelled Trains still to run. */
export interface LineState {
  trains: number;
  live: number;
  scheduled: number;
  unreported: number;
  late5: number;
  worst: number;
  cancelled: number;
}

export interface Row {
  time: string;
  minutes: number;
  line: string;
  headsign: string;
  live: boolean;
  delay?: number;
  cancelled?: true;
  skipped?: true;
  unreported?: true;
  number?: string;
}

export interface Board {
  id: string;
  name: string;
  lines: string[];
  departures: Row[];
}

export interface TrainNow {
  trip: string;
  number?: string;
  line: string;
  headsign: string;
  live: boolean;
  unreported?: true;
  delay?: number;
}

export interface CancelledTrain {
  trip: string;
  number?: string;
  line: string;
  headsign: string;
  from: string;
  leaves: string;
  arrives: string;
  network?: string;
}

export interface AlertRow {
  id: string;
  lines: string[];
  header?: string;
  text: string;
  language?: string;
  from?: number;
  by: string;
}

export interface LineScreen {
  id: string;
  name: string;
  title: string;
  colour: string;
  network: string;
  stations: { id: string; name: string; calls: number; starts: number; ends: number }[];
  trains: (TrainNow & {
    next?: { station: string; at: string; minutes: number };
    standsAt?: number;
    after: number;
    way: number;
    speed: number;
    since?: number;
    unit?: string;
    variant: string;
  })[];
  variants: { from: string; to: string; fromName: string; toName: string; trips: number; stations: number; key: string; calls: string[] }[];
  cancelled: CancelledTrain[];
  state: LineState;
  alerts: AlertRow[];
}

export interface NetworkNow {
  id: string;
  name: string;
  trains: number;
  live: number;
  unreported: number;
  late5: number;
  cancelled: number;
  unavailable: boolean;
  feedAgo?: number;
  hasLive: boolean;
  lines: ({ id: string } & LineState)[];
  first?: { at: string; line: string; from: string; to: string };
  last?: { at: string; line: string; from: string; to: string; leaves: string };
}

export interface NowScreen {
  networks: NetworkNow[];
  latest?: TrainNow & { from: string; next?: string; leaves: string };
  specials: { id: string; running: TrainNow[]; next?: { at: string; from: string; to: string }; network: string }[];
  france: { trip: string; number?: string; line: string; headsign: string; from: string; leaves: string; border: string; ended: boolean; running?: { live: boolean; delay?: number }; cancelled?: true; into: boolean }[];
  closures: { line: string; kind: 'closed' | 'single'; stations: (string | undefined)[]; hides?: true; from?: number }[];
  cancelled: CancelledTrain[];
}

export interface SearchResults {
  query: string;
  stations: { id: string; name: string; networks: string[]; lines: string[] }[];
  lines: { id: string; state: LineState; title?: string; alerts: number }[];
  numbers: { trip: string; number: string; line: string; headsign: string; from?: string; leaves: string; arrives: string; state: 'running' | 'later' | 'ended' | 'cancelled'; live?: boolean; delay?: number; unreported?: true; next?: { station?: string; at: string } }[];
}

